CREATE TABLE public.popup_leads (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now(), campaign text NOT NULL, campaign_name text NOT NULL, name text NOT NULL CHECK (length(name) BETWEEN 2 AND 100), phone text NOT NULL CHECK (length(phone) BETWEEN 7 AND 25), interest text NOT NULL CHECK (length(interest) BETWEEN 1 AND 200), mode text NOT NULL CHECK (mode IN ('Offline — Ahmedabad', 'Live online')), consent boolean NOT NULL CHECK (consent), status text NOT NULL DEFAULT 'new' CHECK (status IN ('new','contacted','enrolled','closed')), notes text NOT NULL DEFAULT '' CHECK (length(notes) <= 5000));
GRANT SELECT, UPDATE ON public.popup_leads TO authenticated;
GRANT ALL ON public.popup_leads TO service_role;
ALTER TABLE public.popup_leads ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Owner popup lead read" ON public.popup_leads FOR SELECT TO authenticated USING (public.has_role(auth.uid(), 'admin'));
CREATE POLICY "Owner popup lead update" ON public.popup_leads FOR UPDATE TO authenticated USING (public.has_role(auth.uid(), 'admin')) WITH CHECK (public.has_role(auth.uid(), 'admin'));
CREATE OR REPLACE FUNCTION public.save_website_content(payload jsonb, publish_now boolean, expected_version integer) RETURNS integer LANGUAGE plpgsql SECURITY INVOKER SET search_path = public AS $$ DECLARE new_version integer; live_payload jsonb; BEGIN IF NOT public.has_role(auth.uid(), 'admin') THEN RAISE EXCEPTION 'Forbidden'; END IF; live_payload := jsonb_set(payload, '{articles}', COALESCE((SELECT jsonb_agg(article) FROM jsonb_array_elements(payload->'articles') AS article WHERE COALESCE(article->>'status', 'published') = 'published'), '[]'::jsonb)); INSERT INTO public.website_content(key) VALUES ('site') ON CONFLICT DO NOTHING; UPDATE public.website_content SET draft = payload, published = CASE WHEN publish_now THEN live_payload ELSE published END, version = version + 1, updated_at = now() WHERE key = 'site' AND version = expected_version RETURNING version INTO new_version; IF new_version IS NULL THEN RAISE EXCEPTION 'Content changed. Reload before saving.'; END IF; INSERT INTO public.content_history(user_id, content, action) VALUES(auth.uid(), payload, CASE WHEN publish_now THEN 'published' ELSE 'draft saved' END); RETURN new_version; END; $$;
REVOKE ALL ON FUNCTION public.save_website_content(jsonb, boolean, integer) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.save_website_content(jsonb, boolean, integer) TO authenticated;